// ---------------------------------------------------------------
// from: family_account_consent/widgets/pulsing_brand_dot.dart
// ---------------------------------------------------------------
class PulsingBrandDot extends StatefulWidget {
  const PulsingBrandDot({super.key, this.size = 6});

  final double size;

  @override
  State<PulsingBrandDot> createState() => _PulsingBrandDotState();
}

class _PulsingBrandDotState extends State<PulsingBrandDot>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    // The CSS keyframes run 0% -> 50% -> 100% over 2.4s; a 1.2s
    // reverse-repeating controller reproduces the same ease-in-out cycle.
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1200),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, child) {
        final double t = Curves.easeInOut.transform(_controller.value);
        final double spread = 3 + (3 * t); // 3px -> 6px
        final int alpha = (36 + (13 - 36) * t).round(); // .14 -> .05 alpha
        return Container(
          width: widget.size,
          height: widget.size,
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            color: AppColors.primary,
            boxShadow: [
              BoxShadow(
                color: AppColors.primary.withAlpha(alpha),
                spreadRadius: spread,
                blurRadius: 0,
              ),
            ],
          ),
        );
      },
    );
  }
}

