// from: family_account_consent/widgets/status_pill.dart
// ---------------------------------------------------------------
class StatusPill extends StatelessWidget {
  const StatusPill({super.key, required this.status, this.onConnectTap});

  final FamilyMemberStatus status;
  final VoidCallback? onConnectTap;

  @override
  Widget build(BuildContext context) {
    final scope = AppScope.of(context);
    return switch (status) {
      FamilyMemberStatus.connected => _buildPill(
          label: scope.t('family_statusConnected'),
          background: AppColors.successBg,
          textColor: AppColors.success,
        ),
      FamilyMemberStatus.pending => _buildPill(
          label: scope.t('family_statusPending'),
          background: theme.AppColors.surf(context),
          textColor: theme.AppColors.mutedOf(context),
        ),
      FamilyMemberStatus.connectable => GestureDetector(
          onTap: onConnectTap,
          child: _buildPill(
            label: scope.t('family_statusConnect'),
            background: Colors.transparent,
            textColor: AppColors.primary,
            border: Border.all(color: AppColors.primary),
          ),
        ),
    };
  }

  Widget _buildPill({
    required String label,
    required Color background,
    required Color textColor,
    Border? border,
  }) {
    return Container(
      padding: const EdgeInsetsDirectional.symmetric(horizontal: 10, vertical: 5),
      decoration: BoxDecoration(
        color: background,
        border: border,
        borderRadius: BorderRadius.circular(100),
      ),
      child: Text(
        label,
        style: AppTextStyles.statusPill.copyWith(color: textColor),
      ),
    );
  }
}

