class AppPrimaryButton extends StatefulWidget {
  const AppPrimaryButton({
    super.key,
    required this.label,
    required this.enabled,
    required this.onPressed,
    this.loading = false,
    this.loadingLabel,
    this.mutedStyle = false,
  });

  final String label;
  final bool enabled;
  final VoidCallback? onPressed;
  final bool loading;
  final String? loadingLabel;

  /// Matches the "Done" button variant, which reuses .btn-primary but with
  /// a surface background and heading-colored text instead of the red fill.
  final bool mutedStyle;

  @override
  State<AppPrimaryButton> createState() => _AppPrimaryButtonState();
}

class _AppPrimaryButtonState extends State<AppPrimaryButton> {
  bool _pressed = false;

  @override
  Widget build(BuildContext context) {
    final scope = AppScope.of(context);
    final bool isActive = widget.enabled && !widget.loading;
    final Color background = widget.mutedStyle
        ? theme.AppColors.surf(context)
        : (isActive ? AppColors.primary : theme.AppColors.surf(context));
    final Color textColor = widget.mutedStyle
        ? theme.AppColors.textP(context)
        : (isActive ? Colors.white : theme.AppColors.mutedOf(context));
    final List<BoxShadow> shadow = (isActive && !widget.mutedStyle)
        ? [
            BoxShadow(
              color: AppColors.primary.withOpacity(0.45),
              blurRadius: 20,
              offset: const Offset(0, 8),
              spreadRadius: -8,
            ),
          ]
        : const [];

    return GestureDetector(
      onTapDown: isActive ? (_) => setState(() => _pressed = true) : null,
      onTapUp: isActive ? (_) => setState(() => _pressed = false) : null,
      onTapCancel: isActive ? () => setState(() => _pressed = false) : null,
      onTap: isActive ? widget.onPressed : null,
      child: AnimatedScale(
        scale: _pressed ? 0.99 : 1.0,
        duration: const Duration(milliseconds: 150),
        curve: Curves.easeOut,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 150),
          curve: Curves.easeOut,
          width: double.infinity,
          padding: const EdgeInsetsDirectional.all(16),
          decoration: BoxDecoration(
            color: background,
            borderRadius: BorderRadius.circular(100),
            boxShadow: shadow,
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            mainAxisSize: MainAxisSize.min,
            children: widget.loading
                ? [
                    SizedBox(
                      width: 17,
                      height: 17,
                      child: CircularProgressIndicator(
                        strokeWidth: 2,
                        valueColor: AlwaysStoppedAnimation(
                          widget.mutedStyle ? theme.AppColors.textP(context) : Colors.white,
                        ),
                        backgroundColor: widget.mutedStyle
                            ? theme.AppColors.textP(context).withOpacity(0.2)
                            : const Color(0x59FFFFFF),
                      ),
                    ),
                    const SizedBox(width: 9),
                    Text(
                      widget.loadingLabel ?? scope.t('family_connecting'),
                      style: AppTextStyles.btnPrimary.copyWith(
                        color: widget.mutedStyle ? theme.AppColors.textP(context) : Colors.white,
                      ),
                    ),
                  ]
                : [
                    Text(
                      widget.label,
                      style: AppTextStyles.btnPrimary.copyWith(
                        color: textColor,
                      ),
                    ),
                  ],
          ),
        ),
      ),
    );
  }
}

