// ---------------------------------------------------------------
// from: family_account_consent/widgets/success_link_graphic.dart
// ---------------------------------------------------------------
/// Recreates the `.link-node-wrap` graphic: two avatar "nodes" connected by
/// a line that draws in, plus a pulse dot that continuously travels from
/// node A to node B once the entrance animation has settled.
class SuccessLinkGraphic extends StatefulWidget {
  const SuccessLinkGraphic({super.key, required this.active});

  final bool active;

  @override
  State<SuccessLinkGraphic> createState() => _SuccessLinkGraphicState();
}

class _SuccessLinkGraphicState extends State<SuccessLinkGraphic>
    with TickerProviderStateMixin {
  static const int _entranceMs = 750;

  late final AnimationController _entranceController;
  late final AnimationController _pulseController;

  @override
  void initState() {
    super.initState();
    _entranceController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: _entranceMs),
    );
    _pulseController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1400),
    );
    if (widget.active) _play();
  }

  @override
  void didUpdateWidget(covariant SuccessLinkGraphic oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.active && !oldWidget.active) {
      _play();
    } else if (!widget.active && oldWidget.active) {
      _stop();
    }
  }

  void _play() {
    _entranceController.forward(from: 0);
    _pulseController.stop();
    _pulseController.reset();
    // CSS: .link-pulse animation-delay is .75s, independent of the entrance
    // timings, so it is scheduled the same way here.
    Future.delayed(const Duration(milliseconds: 750), () {
      if (mounted && widget.active) {
        _pulseController.repeat();
      }
    });
  }

  void _stop() {
    _entranceController.stop();
    _entranceController.reset();
    _pulseController.stop();
    _pulseController.reset();
  }

  @override
  void dispose() {
    _entranceController.dispose();
    _pulseController.dispose();
    super.dispose();
  }

  Animation<double> _interval(int startMs, int durationMs) {
    final double start = startMs / _entranceMs;
    final double end = ((startMs + durationMs) / _entranceMs).clamp(0.0, 1.0);
    return CurvedAnimation(
      parent: _entranceController,
      curve: Interval(start, end, curve: Curves.easeOutCubic),
    );
  }

  @override
  Widget build(BuildContext context) {
    final Animation<double> nodeA = _interval(0, 500);
    final Animation<double> nodeB = _interval(50, 500);
    final Animation<double> line = _interval(150, 600);

    const double wrapWidth = 180;
    const double wrapHeight = 70;
    const double nodeSize = 46;

    return SizedBox(
      width: wrapWidth,
      height: wrapHeight,
      child: AnimatedBuilder(
        animation: Listenable.merge([_entranceController, _pulseController]),
        builder: (context, child) {
          return Stack(
            clipBehavior: Clip.none,
            children: [
              // Connecting line
              PositionedDirectional(
                top: 35,
                start: nodeSize,
                end: nodeSize,
                height: 2,
                child: Transform(
                  alignment: AlignmentDirectional.centerStart,
                  transform: Matrix4.identity()..scale(line.value, 1.0),
                  child: Container(color: AppColors.primary.withOpacity(0.35)),
                ),
              ),
              // Traveling pulse dot
              _buildPulseDot(wrapWidth),
              // Node A (parent)
              PositionedDirectional(
                top: 12,
                start: 0,
                child: Opacity(
                  opacity: nodeA.value.clamp(0.0, 1.0),
                  child: Transform.scale(
                    scale: 0.6 + (0.4 * nodeA.value),
                    child: _buildNode(
                      label: 'PA',
                      background: theme.AppColors.surf(context),
                      textColor: theme.AppColors.textP(context),
                      border: Border.all(color: theme.AppColors.border(context)),
                    ),
                  ),
                ),
              ),
              // Node B (child)
              PositionedDirectional(
                top: 12,
                end: 0,
                child: Opacity(
                  opacity: nodeB.value.clamp(0.0, 1.0),
                  child: Transform.scale(
                    scale: 0.6 + (0.4 * nodeB.value),
                    child: _buildNode(
                      label: 'CH',
                      background: AppColors.primary,
                      textColor: Colors.white,
                      border: null,
                    ),
                  ),
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildPulseDot(double wrapWidth) {
    final double t = _pulseController.value;
    double opacity;
    if (t < 0.1) {
      opacity = t / 0.1;
    } else if (t > 0.9) {
      opacity = (1 - t) / 0.1;
    } else {
      opacity = 1.0;
    }
    final double leftFraction = 0.16 + (0.84 - 0.16) * t;
    final double centerX = leftFraction * wrapWidth;

    return PositionedDirectional(
      top: 31,
      start: centerX - 5,
      child: Opacity(
        opacity: _pulseController.isAnimating ? opacity.clamp(0.0, 1.0) : 0.0,
        child: Container(
          width: 10,
          height: 10,
          decoration: const BoxDecoration(
            color: AppColors.primary,
            shape: BoxShape.circle,
          ),
        ),
      ),
    );
  }

  Widget _buildNode({
    required String label,
    required Color background,
    required Color textColor,
    Border? border,
  }) {
    return Container(
      width: 46,
      height: 46,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: background,
        borderRadius: BorderRadius.circular(14),
        border: border,
      ),
      child: Text(
        label,
        style: AppTextStyles.avatarInitials.copyWith(color: textColor),
      ),
    );
  }
}

