// ---------------------------------------------------------------
// from: family_account_consent/widgets/family_member_row.dart
// ---------------------------------------------------------------
class FamilyMemberRow extends StatelessWidget {
  const FamilyMemberRow({
    super.key,
    required this.member,
    this.showBottomBorder = true,
    this.onConnectTap,
  });

  final FamilyMember member;
  final bool showBottomBorder;
  final VoidCallback? onConnectTap;

  @override
  Widget build(BuildContext context) {
    final scope = AppScope.of(context);
    final bool isConnected = member.status == FamilyMemberStatus.connected;
    String? displayName;
    String? displayRel;
    switch (member.initials) {
      case 'PA':
        displayName = scope.t('family_memberParentName');
        displayRel = scope.t('family_memberParentRel');
        break;
      case 'CH':
        displayName = scope.t('family_memberChildName');
        displayRel = scope.t('family_memberChildRel');
        break;
      case 'SI':
        displayName = scope.t('family_memberSiblingName');
        displayRel = scope.t('family_memberSiblingRel');
        break;
    }

    return Container(
      padding: const EdgeInsetsDirectional.symmetric(horizontal: 4, vertical: 12),
      decoration: BoxDecoration(
        border: showBottomBorder
            ? Border(bottom: BorderSide(color: theme.AppColors.border(context)))
            : null,
      ),
      child: Row(
        children: [
          _buildAvatar(isConnected, context),
          const SizedBox(width: 13),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(displayName ?? member.name, style: AppTextStyles.memberName.copyWith(color: theme.AppColors.textP(context))),
                const SizedBox(height: 1),
                Text(displayRel ?? member.relationship, style: AppTextStyles.memberRel.copyWith(color: theme.AppColors.mutedOf(context))),
              ],
            ),
          ),
          StatusPill(status: member.status, onConnectTap: onConnectTap),
        ],
      ),
    );
  }

  Widget _buildAvatar(bool isConnected, BuildContext context) {
    final Widget avatar = Container(
      width: 46,
      height: 46,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: member.tintedAvatar ? AppColors.primaryTint : theme.AppColors.surf(context),
        borderRadius: BorderRadius.circular(14),
      ),
      child: Text(
        member.initials,
        style: member.tintedAvatar
            ? AppTextStyles.avatarInitialsTint
            : AppTextStyles.avatarInitials.copyWith(color: theme.AppColors.textP(context)),
      ),
    );

    if (!isConnected) return avatar;

    // Recreates `.avatar .ring` — an absolutely positioned border sitting
    // 3px outside the avatar box, only visible on the connected member.
    return Stack(
      clipBehavior: Clip.none,
      children: [
        avatar,
        PositionedDirectional(
          start: -3,
          end: -3,
          top: -3,
          bottom: -3,
          child: DecoratedBox(
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: AppColors.success, width: 1.5),
            ),
          ),
        ),
      ],
    );
  }
}

