// from: family_account_consent/widgets/family_card.dart
// ---------------------------------------------------------------
class FamilyCard extends StatelessWidget {
  const FamilyCard({super.key, required this.members, this.onConnectTap});

  final List<FamilyMember> members;
  final ValueChanged<FamilyMember>? onConnectTap;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsetsDirectional.all(18),
      decoration: BoxDecoration(
        color: theme.AppColors.cardBgOf(context),
        border: Border.all(color: theme.AppColors.border(context)),
        borderRadius: BorderRadius.circular(AppColors.radiusLg),
        boxShadow: const [
          BoxShadow(
            color: AppColors.cardShadow,
            blurRadius: 3,
            offset: Offset(0, 1),
          ),
        ],
      ),
      child: Column(
        children: [
          for (int i = 0; i < members.length; i++)
            FamilyMemberRow(
              member: members[i],
              showBottomBorder: i != members.length - 1,
              onConnectTap: onConnectTap == null
                  ? null
                  : () => onConnectTap!(members[i]),
            ),
        ],
      ),
    );
  }
}

// ---------------------------------------------------------------
// from: family_account_consent/pages/family_account_consent_page.dart
// ---------------------------------------------------------------
class FamilyAccountConsentPage extends StatefulWidget {
  const FamilyAccountConsentPage({super.key});

  @override
  State<FamilyAccountConsentPage> createState() =>
      _FamilyAccountConsentPageState();
}

class _FamilyAccountConsentPageState extends State<FamilyAccountConsentPage> {
  bool _consentChecked = false;
  bool _isConnecting = false;
  bool _showSuccess = false;

  final List<FamilyMember> _members = const [
    FamilyMember(
      initials: 'PA',
      name: 'Parent',
      relationship: 'Parent',
      status: FamilyMemberStatus.connected,
      tintedAvatar: true,
    ),
    FamilyMember(
      initials: 'CH',
      name: 'Child',
      relationship: 'Child',
      status: FamilyMemberStatus.pending,
    ),
    FamilyMember(
      initials: 'SI',
      name: 'Sibling',
      relationship: 'Sibling',
      status: FamilyMemberStatus.connectable,
    ),
  ];

  void _handleConnectPressed() {
    if (!_consentChecked || _isConnecting) return;
    setState(() => _isConnecting = true);
    // Matches the original setTimeout(..., 1200) "Connecting…" delay before
    // swapping to the success panel.
    Future.delayed(const Duration(milliseconds: 1200), () {
      if (!mounted) return;
      setState(() {
        _isConnecting = false;
        _showSuccess = true;
      });
    });
  }

  void _handleDonePressed() {
    Navigator.of(context).maybePop(true);
  }

  void _handleNotNowPressed() {
    Navigator.of(context).maybePop(false);
  }

  @override
  Widget build(BuildContext context) {
    final scope = AppScope.of(context);
    return Scaffold(
      backgroundColor: theme.AppColors.bg(context),
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 412),
            child: SingleChildScrollView(
              padding:
                  const EdgeInsetsDirectional.symmetric(horizontal: 16, vertical: 48),
              child: Container(
                width: double.infinity,
                padding: const EdgeInsetsDirectional.fromSTEB(20, 28, 20, 32),
                decoration: BoxDecoration(
                  color: theme.AppColors.bg(context),
                  border: Border.all(color: theme.AppColors.border(context)),
                  borderRadius: BorderRadius.circular(32),
                  boxShadow: const [
                    BoxShadow(
                      color: AppColors.screenShadow,
                      blurRadius: 24,
                      offset: Offset(0, 4),
                    ),
                  ],
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    BrandHeader(onClose: () => Navigator.of(context).maybePop(false)),
                    const SizedBox(height: 22),
                    Text(scope.t('family_safetyTitle'), style: AppTextStyles.heading1.copyWith(color: theme.AppColors.textP(context))),
                    const SizedBox(height: 8),
                    SizedBox(
                      width: 230,
                      child: Text(
                        scope.t('family_safetySubtitle'),
                        style: AppTextStyles.headerParagraph.copyWith(color: theme.AppColors.textS(context)),
                      ),
                    ),
                    const SizedBox(height: 26),
                    Padding(
                      padding: const EdgeInsetsDirectional.only(bottom: 20),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          SectionEyebrow(scope.t('family_yourFamilyLabel')),
                          FamilyCard(members: _members),
                        ],
                      ),
                    ),
                    const Padding(
                      padding: EdgeInsetsDirectional.only(bottom: 20),
                      child: PermissionsSection(),
                    ),
                    _showSuccess
                        ? ConsentSuccessView(
                            active: _showSuccess,
                            onDonePressed: _handleDonePressed,
                          )
                        : ConsentDefaultView(
                            consentChecked: _consentChecked,
                            onConsentChanged: (value) =>
                                setState(() => _consentChecked = value),
                            isConnecting: _isConnecting,
                            onConnectPressed: _handleConnectPressed,
                            onNotNowPressed: _handleNotNowPressed,
                          ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

